function renderToolChest(){const list=$("toolChestList");if(!list)return;list.innerHTML="";$("toolChestCount").textContent=`${toolChest.length} ${toolChest.length===1?"tool":"tools"}`;$("toolChestEmpty").hidden=Boolean(toolChest.length);$("exportToolChestButton").disabled=!toolChest.length;$("saveSelectedTool").disabled=!selectedToolChestItem();for(const tool of toolChest){const row=document.createElement("div");row.className="tool-chest-item";row.classList.toggle("active",activeToolChestTool?.id===tool.id);row.tabIndex=0;row.setAttribute("role","button");const preview=toolChestPreview(tool),details=document.createElement("div"),name=document.createElement("strong"),kind=document.createElement("small");name.textContent=tool.name;kind.textContent=`${toolLabel(tool.kind)}${tool.source==="bluebeam"?" · BTX":""}`;details.append(name,kind);const remove=document.createElement("button");remove.type="button";remove.title="Remove tool";remove.setAttribute("aria-label",`Remove ${tool.name}`);remove.innerHTML='<span class="ui-icon icon-trash" aria-hidden="true"></span>';remove.onclick=event=>{event.stopPropagation();toolChest=toolChest.filter(item=>item.id!==tool.id);if(activeToolChestTool?.id===tool.id)activeToolChestTool=null;saveToolChest();renderToolChest();};const activate=()=>activateChestTool(tool);row.onclick=activate;row.onkeydown=event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();activate();}};row.append(preview,details,remove);list.append(row);}}
